  | {
      readonly status: 'read'
      readonly document: HostPath
      readonly snapshot: ReviewDocumentSnapshot
      readonly content: string
    }
  | {
      readonly status: 'stale'
      readonly document: HostPath
      readonly reason: 'deleted' | 'host-unavailable' | 'incomplete-read' | 'invalid-text'
    }

